/* Same original connection, independent M/P accounting, no second pool. */
#define NR_PHYSICAL_SCHEMA \
 "CREATE TABLE root_physical_policy(kind INTEGER PRIMARY KEY CHECK(kind IN (1,2)),owner_digest TEXT NOT NULL,issuer_json TEXT NOT NULL,capacity INTEGER NOT NULL,queue_limit INTEGER NOT NULL,next_seq INTEGER NOT NULL,human_burst INTEGER NOT NULL,claim_seq INTEGER NOT NULL);" \
 "CREATE TABLE root_physical_resources(record_id TEXT PRIMARY KEY,resource_kind INTEGER NOT NULL CHECK(resource_kind IN (1,2)),execution_class TEXT NOT NULL,execution_key TEXT UNIQUE NOT NULL,metadata_json TEXT NOT NULL,metadata_digest TEXT NOT NULL,enqueue_seq INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN ('queued','reserved','unknown','released')),claim_token TEXT,generation INTEGER NOT NULL,issuer_epoch INTEGER NOT NULL,allocation_role TEXT NOT NULL CHECK(allocation_role IN ('direct','workflow_vm','workflow_child_slot','workflow_child_attempt')),parent_record_id TEXT,native_root_id TEXT,UNIQUE(resource_kind,enqueue_seq),FOREIGN KEY(parent_record_id) REFERENCES root_physical_resources(record_id),FOREIGN KEY(native_root_id) REFERENCES root_resources(record_id),CHECK(resource_kind=2 OR allocation_role='direct'),CHECK((allocation_role IN ('direct','workflow_vm') AND parent_record_id IS NULL) OR (allocation_role IN ('workflow_child_slot','workflow_child_attempt') AND parent_record_id IS NOT NULL)),CHECK(allocation_role='direct' OR native_root_id IS NOT NULL));" \
 "CREATE UNIQUE INDEX root_physical_workflow_vm ON root_physical_resources(native_root_id) WHERE allocation_role='workflow_vm';" \
 "CREATE UNIQUE INDEX root_physical_workflow_slot ON root_physical_resources(parent_record_id) WHERE allocation_role='workflow_child_slot';" \
 "CREATE UNIQUE INDEX root_physical_workflow_armed ON root_physical_resources(parent_record_id) WHERE allocation_role='workflow_child_attempt' AND state IN ('reserved','unknown');" \
 "CREATE TABLE root_physical_receipts(record_id TEXT NOT NULL,kind TEXT NOT NULL,binding_hash TEXT NOT NULL,receipt_json TEXT NOT NULL,PRIMARY KEY(record_id,kind),FOREIGN KEY(record_id) REFERENCES root_physical_resources(record_id));"
